//! `tpt-home-bp-track` — Simple Tracker.
//!
//! Relational data with *user-defined* tables and fields. Safety model for
//! dynamic SQL: data tables are named `track_data_<table_id>` and columns
//! `f_<field_id>` — every dynamic identifier is an integer generated by the
//! database itself, so user input can never become SQL syntax. Values are
//! bound as parameters and validated against the declared field kind.

use tpt_home_core::prelude::*;
use tpt_home_macros::{blueprint, bp_migration, bp_route, bp_ui_route};

pub mod api;
pub mod csv_io;
pub mod page;

/// Track blueprint metadata.
#[blueprint(id = "track", name = "Track")]
pub struct TrackBlueprint;

#[bp_migration]
const SCHEMA: &str = r#"
    CREATE TABLE IF NOT EXISTS track_tables (
        id         INTEGER PRIMARY KEY,
        name       TEXT    NOT NULL,
        created_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS track_fields (
        id       INTEGER PRIMARY KEY,
        table_id INTEGER NOT NULL REFERENCES track_tables(id) ON DELETE CASCADE,
        name     TEXT    NOT NULL,
        kind     TEXT    NOT NULL CHECK (kind IN ('text', 'integer', 'real', 'bool')),
        position INTEGER NOT NULL DEFAULT 0,
        UNIQUE (table_id, name)
    );
"#;

#[bp_route(get, "/api/track/tables")]
async fn list_tables(State(db): State<DbPool>) -> Result<impl IntoResponse, ApiError> {
    Ok(Json(api::list_tables(&db).await?))
}

#[bp_route(post, "/api/track/tables")]
async fn create_table(
    State(db): State<DbPool>,
    Json(body): Json<api::CreateTable>,
) -> Result<impl IntoResponse, ApiError> {
    let table = api::create_table(&db, body).await?;
    Ok((axum::http::StatusCode::CREATED, Json(table)))
}

#[bp_route(delete, "/api/track/tables/{id}")]
async fn delete_table(
    State(db): State<DbPool>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<impl IntoResponse, ApiError> {
    api::delete_table(&db, id).await?;
    Ok(Json(serde_json::json!({ "ok": true })))
}

#[bp_route(get, "/api/track/tables/{id}/rows")]
async fn list_rows(
    State(db): State<DbPool>,
    axum::extract::Path(id): axum::extract::Path<i64>,
    axum::extract::RawQuery(query): axum::extract::RawQuery,
) -> Result<impl IntoResponse, ApiError> {
    Ok(Json(api::list_rows(&db, id, query).await?))
}

#[bp_route(post, "/api/track/tables/{id}/rows")]
async fn create_row(
    State(db): State<DbPool>,
    axum::extract::Path(id): axum::extract::Path<i64>,
    Json(values): Json<serde_json::Map<String, serde_json::Value>>,
) -> Result<impl IntoResponse, ApiError> {
    api::create_row(&db, id, values).await?;
    Ok((
        axum::http::StatusCode::CREATED,
        Json(serde_json::json!({ "ok": true })),
    ))
}

#[bp_route(patch, "/api/track/tables/{id}/rows/{row}")]
async fn update_row(
    State(db): State<DbPool>,
    axum::extract::Path((id, row)): axum::extract::Path<(i64, i64)>,
    Json(values): Json<serde_json::Map<String, serde_json::Value>>,
) -> Result<impl IntoResponse, ApiError> {
    api::update_row(&db, id, row, values).await?;
    Ok(Json(serde_json::json!({ "ok": true })))
}

#[bp_route(delete, "/api/track/tables/{id}/rows/{row}")]
async fn delete_row(
    State(db): State<DbPool>,
    axum::extract::Path((id, row)): axum::extract::Path<(i64, i64)>,
) -> Result<impl IntoResponse, ApiError> {
    api::delete_row(&db, id, row).await?;
    Ok(Json(serde_json::json!({ "ok": true })))
}

/// GET /api/track/tables/{id}/export.csv: the table as CSV, one row per line.
#[bp_route(get, "/api/track/tables/{id}/export.csv")]
async fn export_csv(
    State(db): State<DbPool>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<axum::response::Response, ApiError> {
    let (name, text) = csv_io::export(&db, id).await?;
    let filename = format!("{}.csv", tpt_home_core::files::sanitize_filename(&name));
    Ok((
        [
            (
                axum::http::header::CONTENT_TYPE,
                "text/csv; charset=utf-8".to_string(),
            ),
            (
                axum::http::header::CONTENT_DISPOSITION,
                format!("attachment; filename=\"{filename}\""),
            ),
        ],
        text,
    )
        .into_response())
}

/// POST /api/track/tables/{id}/import: CSV in the request body (up to 1 MiB).
/// All rows are checked first; if any is bad, nothing is saved.
#[bp_route(post, "/api/track/tables/{id}/import")]
async fn import_csv(
    State(db): State<DbPool>,
    axum::extract::Path(id): axum::extract::Path<i64>,
    body: axum::body::Bytes,
) -> Result<impl IntoResponse, ApiError> {
    let text = std::str::from_utf8(&body)
        .map_err(|_| ApiError::bad_request("the file must be UTF-8 text"))?;
    // Spreadsheet programs often prepend a byte-order mark.
    let text = text.trim_start_matches('\u{feff}');
    let imported = csv_io::import(&db, id, text).await?;
    Ok((
        axum::http::StatusCode::CREATED,
        Json(serde_json::json!({ "imported": imported })),
    ))
}

#[bp_ui_route("/track", name = "Track")]
async fn track_view(axum::Extension(user): axum::Extension<AuthUser>) -> impl IntoResponse {
    page::track_page(&user)
}

/// Link anchor for the binary: see `tpt-home-cli`'s `BLUEPRINT_LINK_ANCHORS`.
/// Never called at runtime; its address forces the linker to keep this
/// crate's registration statics.
#[inline(never)]
pub fn __link_anchor() -> &'static str {
    env!("CARGO_PKG_NAME")
}
